import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { newDbPath, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
}

async function createTask(server: Running, title: string): Promise<Task> {
  const response = await fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
  assert.equal(response.status, 201);
  return ((await response.json()) as { task: Task }).task;
}

async function listTasks(server: Running): Promise<Task[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  return ((await response.json()) as { tasks: Task[] }).tasks;
}

function deleteTask(server: Running, id: number | string): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks/${id}`, { method: "DELETE" });
}

describe("SL-006 delete a task", () => {
  describe("AC-1: an existing task is deleted for good", () => {
    const dbPath = newDbPath();
    let server: Running | undefined;

    after(async () => {
      await server?.stop();
    });

    it("AC-1: DELETE answers 204 and only that task leaves the list", async () => {
      server = await startServer(dbPath);
      const doomed = await createTask(server, "Buy milk");
      const kept = await createTask(server, "Walk the dog");

      const response = await deleteTask(server, doomed.id);
      assert.equal(response.status, 204);
      assert.equal(await response.text(), "");

      assert.deepEqual(
        (await listTasks(server)).map((t) => t.id),
        [kept.id],
      );
    });

    it("AC-1: the task does not return after kill -9 and a restart", async () => {
      assert.ok(server);
      await server.stop();
      server = await startServer(dbPath);

      const tasks = await listTasks(server);
      assert.deepEqual(
        tasks.map((t) => t.title),
        ["Walk the dog"],
      );
    });
  });

  describe("AC-2: a task that no longer exists", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: deleting an id that never existed answers 404 not_found", async () => {
      const response = await deleteTask(server, 9999);
      assert.equal(response.status, 404);
      const body = (await response.json()) as { error: { code: string; message: string } };
      assert.equal(body.error.code, "not_found");
      assert.equal(typeof body.error.message, "string");
    });

    it("AC-2: deleting the same task twice answers 204 and then 404", async () => {
      const task = await createTask(server, "Water plants");
      assert.equal((await deleteTask(server, task.id)).status, 204);
      assert.equal((await deleteTask(server, task.id)).status, 404);
    });

    it("AC-2: a non-numeric id answers 404 too", async () => {
      assert.equal((await deleteTask(server, "abc")).status, 404);
    });
  });

  describe("AC-1: the page asks for a browser confirmation first", () => {
    let script: string;

    before(async () => {
      const server = await startServer();
      try {
        script = await (await fetch(`${server.baseUrl}/app.js`)).text();
      } finally {
        await server.stop();
      }
    });

    it("AC-1: the page script confirms, then sends DELETE to /api/tasks/:id", () => {
      assert.match(script, /confirm\(/);
      assert.match(script, /method:\s*["']DELETE["']/);
      assert.match(script, /\/api\/tasks\/\$\{/);
      assert.ok(script.indexOf("confirm(") < script.indexOf("DELETE"), "confirm comes before DELETE");
      assert.doesNotMatch(script, /innerHTML/);
    });
  });
});
EOF
